const LS_LOCATIONS = 'atlas_live_locations'
const LS_SUGGESTIONS = 'atlas_pending_suggestions'
const LS_CASES = 'atlas_pending_cases'

function load<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key)
    return raw ? JSON.parse(raw) : fallback
  } catch { return fallback }
}

function save(key: string, value: any) {
  try { localStorage.setItem(key, JSON.stringify(value)) } catch {}
}

// Live locations for map + admin
let cachedLocations: MapLocation[] | null = null

export function getMapLocations(): MapLocation[] {
  if (cachedLocations) return cachedLocations
  const stored = load<MapLocation[]>(LS_LOCATIONS, [])
  if (!stored || stored.length === 0) {
    cachedLocations = [...SEED_LOCATIONS]
    save(LS_LOCATIONS, cachedLocations)
    return cachedLocations
  }
  cachedLocations = stored
  return cachedLocations
}

export function saveMapLocations(locs: MapLocation[]) {
  cachedLocations = [...locs]
  save(LS_LOCATIONS, cachedLocations)
}

// Suggestions for moderation (anonymous future submissions)
export function getPendingSuggestions(): LocationSuggestion[] {
  return load(LS_SUGGESTIONS, [])
}

export function addPendingSuggestion(sug: Omit<LocationSuggestion, 'id' | 'reviewed'>) {
  const list = getPendingSuggestions()
  const newItem: LocationSuggestion = { ...sug, id: Date.now(), reviewed: false }
  list.unshift(newItem)
  save(LS_SUGGESTIONS, list)
  return newItem
}

export function removePendingSuggestion(id: number) {
  const list = getPendingSuggestions().filter(s => s.id !== id)
  save(LS_SUGGESTIONS, list)
}

export function markPendingSuggestionReviewed(id: number) {
  const list = getPendingSuggestions().map(s => s.id === id ? {...s, reviewed: true} : s)
  save(LS_SUGGESTIONS, list)
}

// Pending cases (story submissions)
export function getPendingCases(): CaseSubmission[] {
  return load(LS_CASES, [])
}

export function addPendingCase(caseItem: Omit<CaseSubmission, 'id' | 'reviewed' | 'publishedId'>) {
  const list = getPendingCases()
  const newItem: CaseSubmission = { ...caseItem, id: Date.now(), reviewed: false }
  list.unshift(newItem)
  save(LS_CASES, list)
  return newItem
}

export function approvePendingCase(id: number, publishAsPublishedStoryId?: number) {
  const list = getPendingCases()
  const idx = list.findIndex(c => c.id === id)
  if (idx >= 0) {
    list[idx].reviewed = true
    list[idx].publishedId = publishAsPublishedStoryId
  }
  save(LS_CASES, list)
}

export function rejectPendingCase(id: number) {
  const list = getPendingCases().filter(c => c.id !== id)
  save(LS_CASES, list)
}

// Clear all demo data (useful for testing / user reset). Kept hidden.
export function resetAllDemoData() {
  localStorage.removeItem(LS_LOCATIONS)
  localStorage.removeItem(LS_SUGGESTIONS)
  localStorage.removeItem(LS_CASES)
  cachedLocations = null
}
